public static async ValueTask<IDisposable> AcquireConnectionAsync(
    IReadOnlyCollection<string> interfaceIds,
    CancellationToken cancellationToken = default)
{
    ArgumentNullException.ThrowIfNull(interfaceIds);
    if (interfaceIds.Count == 0)
        throw new ArgumentException("At least one interface id is required.", nameof(interfaceIds));

    var uniqueIds = new HashSet<string>(interfaceIds, StringComparer.Ordinal);
    var orderedIds = new string[uniqueIds.Count];
    uniqueIds.CopyTo(orderedIds);
    Array.Sort(orderedIds, StringComparer.Ordinal);

    var acquired = new List<IDisposable>(orderedIds.Length);
    try
    {
        foreach (var id in orderedIds)
        {
            acquired.Add(await GetOwnership(id)
                .AcquireConnectionAsync(id, cancellationToken)
                .ConfigureAwait(false));
        }

        return new CompositeRegistration(acquired);
    }
    catch
    {
        for (var i = acquired.Count - 1; i >= 0; i--)
            acquired[i].Dispose();
        throw;
    }

public async ValueTask<IDisposable> AcquireConnectionAsync(
    string deviceId,
    CancellationToken cancellationToken)
{
    Task discoveryReleased;
    lock (_sync)
    {
        ThrowIfUnrecovered();

        if (!_discoveryActive)
            return Claim(deviceId);

        _waitingConnections++;
        discoveryReleased = _discoveryReleased?.Task
            ?? throw new InvalidOperationException("Discovery ownership has no release signal.");
    }

    try
    {
        await discoveryReleased.WaitAsync(cancellationToken).ConfigureAwait(false);
    }
    catch
    {
        lock (_sync)
            _waitingConnections--;
        throw;
    }

    lock (_sync)
    {
        _waitingConnections--;
        if (_discoveryActive)
            throw new InvalidOperationException("Discovery ownership was reacquired ahead of a waiting connection.");

        ThrowIfUnrecovered();

        return Claim(deviceId);
    }
}

/// <summary>Takes the lease, or refuses when the interface is already held.</summary>
private IDisposable Claim(string deviceId)
{
    ThrowIfUnrecovered();

    if (_connectionCount > 0)
        throw new ConnectionInUseException(
            $"This YubiKey already has a live connection in this process (held interface: '{deviceId}'). " +
            "A physical YubiKey supports one live connection at a time across all interfaces. " +
            "Dispose the existing connection first; connections are reused sequentially, not in parallel.");

    _connectionCount++;
    return new Registration(this, LeaseKind.Connection);

internal static (Dictionary<int, object?> KeyAgreement, byte[] RawSharedSecret)
    PerformEcdhKeyAgreement(IReadOnlyDictionary<int, object?> peerCoseKey)
{
    ArgumentNullException.ThrowIfNull(peerCoseKey);

    // Check coordinate storage here; required kty/alg/crv labels are not yet validated.
    if (!peerCoseKey.TryGetValue(CoseEC2X, out var xObj) || xObj is not byte[] peerX)
    {
        throw new ArgumentException("Peer COSE key missing or invalid X coordinate (-2).", nameof(peerCoseKey));
    }

    if (!peerCoseKey.TryGetValue(CoseEC2Y, out var yObj) || yObj is not byte[] peerY)
    {
        throw new ArgumentException("Peer COSE key missing or invalid Y coordinate (-3).", nameof(peerCoseKey));
    }

    // Validate coordinate lengths (P-256 uses 32-byte coordinates)
    if (peerX.Length != 32)
    {
        throw new ArgumentException($"Invalid X coordinate length: expected 32, got {peerX.Length}.", nameof(peerCoseKey));
    }

    if (peerY.Length != 32)
    {
        throw new ArgumentException($"Invalid Y coordinate length: expected 32, got {peerY.Length}.", nameof(peerCoseKey));
    }

    // Generate ephemeral ECDH key pair
    using var ecdh = ECDiffieHellman.Create(ECCurve.NamedCurves.nistP256);
    var ourParams = ecdh.ExportParameters(includePrivateParameters: false);

    // Import as P-256; provider point-validation errors here are outside the derivation catch.
    var peerParams = new ECParameters
    {
        Curve = ECCurve.NamedCurves.nistP256,
        Q = new ECPoint { X = peerX, Y = peerY }
    };

    using var peerEcdh = ECDiffieHellman.Create(peerParams);

    // Derive raw shared secret (X coordinate of ECDH shared point)
    byte[] z;
    try
    {
        z = ecdh.DeriveRawSecretAgreement(peerEcdh.PublicKey);
    }
    catch (CryptographicException ex)
    {
        throw new ArgumentException("Failed to derive shared secret. Peer key may be invalid.", nameof(peerCoseKey), ex);
    }

    // Build our COSE key for key agreement
    var keyAgreement = new Dictionary<int, object?>
    {
        { CoseKeyType, CoseKeyTypeEC2 },
        { CoseAlgorithm, CoseAlgEcdhEsHkdf256 },
        { CoseEC2Curve, CoseEC2CurveP256 },
        { CoseEC2X, ourParams.Q.X },
        { CoseEC2Y, ourParams.Q.Y }
    };

    catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
    {
        if (!reused)
            _ = ObserveAbandonedEnumerationAsync(enumeration, transport);
        throw;
    }
    catch (OperationCanceledException) when (reused)
    {
        // The reused enumeration honoured an earlier caller's cancellation; nothing is outstanding now.
        outstanding.Task = null;
        return await EnumerateBoundedAsync(outstanding, enumerate, transport, tolerateTimeout, cancellationToken)
            .ConfigureAwait(false);
    }
    catch (TimeoutException)
    {
        if (!reused)
            _ = ObserveAbandonedEnumerationAsync(enumeration, transport);
        cancellationToken.ThrowIfCancellationRequested();
        if (!tolerateTimeout)
        {
            throw new TimeoutException(
                $"{transport} interface enumeration exceeded its {_enumerationBudget} budget; the scan was not published.");
        }

        Logger.LogWarning(
            "{Transport} interface enumeration exceeded its {Budget} budget; continuing without its interfaces this scan.",
            transport, _enumerationBudget);
        return [];
    }
}

private static async Task ObserveAbandonedEnumerationAsync(Task enumeration, string transport)
{
    try
    {
        await enumeration.ConfigureAwait(false);
        Logger.LogDebug("Abandoned {Transport} interface enumeration completed.", transport);
    }
    catch (Exception exception)
    {
        Logger.LogDebug(exception, "Abandoned {Transport} interface enumeration failed.", transport);
    }

public static IDisposable UseTemporary(ILoggerFactory factory)
{
    var original = LoggerFactory;
    LoggerFactory = factory;
    return new RestoreDisposable(() => LoggerFactory = original);
}

private sealed class RestoreDisposable(Action restore) : IDisposable
{
    private Action? _restore = restore;

    public void Dispose()
    {
        _restore?.Invoke();
        _restore = null;

public Task<ReadOnlyMemory<byte>> SendAndReceiveAsync(
    byte command,
    ReadOnlyMemory<byte> payload,
    CancellationToken cancellationToken = default)
{
    ThrowIfDisposed();
    return FidoProtocol.SendCommandAsync(
        command,
        payload,
        UserPresenceNotification.None,
        cancellationToken);

var ownershipTransferred = false;
try
{
    await ReadResponseDataAsync(initPacket, responseData, responseLength, channelId, exchangeToken)
        .ConfigureAwait(false);
    _logger.LogTrace("Received {Length} bytes in response", responseLength);
    terminalResponseDrained = true;

    // Only here is the channel provably clean. Throwing any earlier would strand the
    // remaining frames for the next exchange to misread.
    promptFailure?.Throw();

    // CTAP 2.3 §11.2.9.1.5: a cancelled request "will reply with the error
    // CTAP2_ERR_KEEPALIVE_CANCEL". A touch that raced the cancel yields a real success
    // instead; the authenticator has done the work (a credential may now exist), and the
    // spec never says to discard it, so it is returned.
    if (cancelRequested && !IsCtapSuccess(expectedCommand, responseData))
        callerToken.ThrowIfCancellationRequested();

    ownershipTransferred = true;
    return responseData;

private static bool IsCtapSuccess(byte command, ReadOnlySpan<byte> response) =>
    command == CtapConstants.CtapHidCbor
    && response.Length > 0
    && response[0] == CtapConstants.CtapStatusSuccess;

private static bool IsUserPresenceKeepAlive(ReadOnlySpan<byte> packet) =>
    GetPacketLength(packet) > 0 && packet[CtapConstants.InitHeaderSize] == CtapConstants.KeepAliveStatusUpNeeded;

private static int ValidateTerminalResponse(ReadOnlySpan<byte> packet, uint channelId, byte expectedCommand)
{
    ValidateInitPacket(packet, channelId);
    int responseLength = GetPacketLength(packet);
    if (responseLength > CtapConstants.MaxPayloadSize)
        throw new InvalidOperationException($"Response length {responseLength} exceeds max payload size");

    byte responseCommand = GetPacketCommand(packet);
    if (responseCommand == CtapConstants.CtapHidError)
    {
        byte errorCode = responseLength > 0 ? packet[CtapConstants.InitHeaderSize] : (byte)0x7F;
        throw new InvalidOperationException($"CTAP HID error response: 0x{errorCode:X2}");
    }

    byte normalizedExpectedCommand = (byte)(expectedCommand & ~CtapConstants.InitPacketMask);
    if (responseCommand != normalizedExpectedCommand)
        throw new InvalidOperationException(
            $"CTAP HID response command 0x{responseCommand:X2} does not match request command 0x{expectedCommand:X2}");
